/* Small local creation repository and finite prototype generation jobs. */
(() => {
 const UI=window.PrototypeUI,R=window.PrototypeRecords,KEY='dujia-prototype-works';
 const all=()=>{const data=UI.read(KEY,[]);return Array.isArray(data)?data:[];},find=id=>all().find(v=>v.id===id);
 function put(item){const data=all(),index=data.findIndex(v=>v.id===item.id);if(index<0)data.unshift(item);else data[index]=item;return UI.write(KEY,data);}
 const editor=item=>(item.type==='film'?'m05-p05':item.sourceKind==='photo'?'m05-p04':'m05-p03')+'.html?id='+encodeURIComponent(item.id);
 const route=item=>item.status==='generating'?'m05-p06.html?id='+encodeURIComponent(item.id):item.status==='failed'?'m05-p07.html?id='+encodeURIComponent(item.id):item.status==='ready'?'m05-p08.html?id='+encodeURIComponent(item.id):editor(item);
 const sources=kind=>kind==='moment'?(Array.isArray(UI.read('dujia-prototype-moments',[]))?UI.read('dujia-prototype-moments',[]).filter(v=>v.visibility!=='private'&&v.status!=='draft').map(v=>({id:v.id,title:v.name,body:v.story,image:v.cover})):[]):R.all().filter(v=>v.type===kind&&v.visibility==='shared'&&v.status!=='draft');
 function draft(type='comic',kind='free',selected=[]){return {id:'work-'+crypto.randomUUID(),type,sourceKind:kind,sourceIds:selected.map(v=>v.id),name:selected[0]?.title||'',story:selected.map(v=>v.body||v.title).join('\n'),style:kind==='photo'?'水彩':'暖暖水彩',mode:'温柔叙事',mood:'温柔手帐',characters:UI.read('dujia-characters',{}),status:'draft',createdAt:Date.now(),updatedAt:Date.now()};}
 function start(item){return put({...item,status:'generating',startedAt:Date.now(),dueAt:Date.now()+3000,willFail:UI.failNext('work-generate'),updatedAt:Date.now()});}
 function advance(id){const item=find(id);if(!item||item.status!=='generating'||Date.now()<item.dueAt)return item;const value={...item,status:item.willFail?'failed':'ready',completedAt:Date.now(),updatedAt:Date.now()};return put(value)?value:item;}
 function refresh(){for(const item of all())advance(item.id);return all();}
 const scene=(item,page,index)=>{const sentences=item.story.split(/(?<=[。！？.!?])|\n/).map(v=>v.trim()).filter(Boolean);return sentences.length?sentences[(page*3+index)%sentences.length]:item.name;};
 const image=item=>sources(item.sourceKind).find(v=>item.sourceIds.includes(v.id))?.image||null;
 async function album(item){const id='work-photo-'+item.id,existing=R.find(id);if(existing)return existing;const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1200;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff6e7';ctx.fillRect(0,0,900,1200);ctx.fillStyle='#66432d';ctx.font='36px serif';ctx.fillText(item.name.slice(0,22),50,70);const src=image(item);if(src){const img=new Image();img.src=src;await img.decode();const ratio=Math.min(800/img.width,650/img.height);ctx.drawImage(img,(900-img.width*ratio)/2,120,img.width*ratio,img.height*ratio);}else{const img=new Image();img.src='../assets/m05-p08-art.webp';await img.decode();ctx.drawImage(img,65,340,740,890,80,140,740,650);}ctx.font='24px serif';let y=850;for(let i=0;i<Math.min(item.story.length,240);i+=28){ctx.fillText(item.story.slice(i,i+28),50,y);y+=34;}const value={id,type:'photo',title:item.name,body:item.story,image:canvas.toDataURL('image/png'),tags:['童话工坊'],visibility:'shared',status:'published',author:UI.read('dujia-profile',{})?.nickname||'小满',workId:item.id,date:new Date().toISOString().slice(0,10),createdAt:Date.now(),updatedAt:Date.now(),comments:[]};return R.put(value)?value:null;}
 window.PrototypeWorkshop={all,find,put,draft,start,advance,refresh,editor,route,sources,scene,image,album,key:KEY};
})();
